/// Convert user-facing surface facets to the compact facet arrays used by
/// [`tetrahedralize_surface`].
pub(super) fn collect_surface_facets(
    facets: &[SurfaceFacet],
) -> (Vec<[usize; 3]>, Option<Vec<i32>>) {
    let mut nodes = Vec::with_capacity(facets.len());
    let mut markers: Vec<i32> = Vec::with_capacity(facets.len());
    let mut has_markers = false;

    for facet in facets {
        nodes.push(facet.nodes);
        let marker = facet.marker.unwrap_or(0);
        if facet.marker.is_some() {
            has_markers = true;
        }
        markers.push(marker);
    }

    if has_markers {
        (nodes, Some(markers))
    } else {
        (nodes, None)
    }
}

